import math
def calculate_dbf(task, t):
    if t < task.D:
        return 0
    num_jobs = math.floor((t - task.D) / task.T) + 1
    return num_jobs * task.C

def calculate_ff_dbf(task, t, sigma):
    q_k = math.floor(t / task.T)
    r_k = t % task.T

    if r_k >= task.D:
        return q_k * task.C + task.C
    elif task.D > r_k and r_k >= task.D - task.C * sigma:
        return q_k * task.C + task.C - (task.D - r_k) * sigma
    else:
        return q_k * task.C

def calculate_max_mode_density(mode_tasks):
    max_density = 0
    for task in mode_tasks:
        density = task.C / task.D
        if density > max_density:
            max_density = density
    return max_density

def calculate_sum_mode_density(mode_tasks):
    sum_density = 0
    for task in mode_tasks:
        density = task.C / task.D
        sum_density += density
    return sum_density

def calculate_dbf_for_task_set(task_set, t):
    total_dbf = 0
    for task in task_set:
        total_dbf += calculate_dbf(task, t) # Assuming calculate_dbf is defined
    return total_dbf

def calculate_ff_dbf_for_task_set(task_set, t, sigma):
    total_ff_dbf = 0
    for task in task_set:
        total_ff_dbf += calculate_ff_dbf(task, t, sigma) # Assuming calculate_ff_dbf is defined
    return total_ff_dbf

def calculate_load(task_set, max_t_to_check):
    max_ratio = 0
    for t in range(1, max_t_to_check + 1):
        dbf_val = calculate_dbf_for_task_set(task_set, t) # Assuming defined
        ratio = dbf_val / t
        if ratio > max_ratio:
            max_ratio = ratio
    return max_ratio

def calculate_ff_load(task_set, sigma, max_t_to_check):
    max_ratio = 0
    for t in range(1, max_t_to_check + 1):
        ff_dbf_val = calculate_ff_dbf_for_task_set(task_set, t, sigma) # Assuming defined
        ratio = ff_dbf_val / t
        if ratio > max_ratio:
            max_ratio = ratio
    return max_ratio

def bound_mi_task_work(mi_task_set, interval_start, interval_end, sigma):
    interval_length = interval_end - interval_start
    # The actual work done is bounded by the FF-DBF
    return calculate_ff_dbf_for_task_set(mi_task_set, interval_length, sigma)

def bound_mode_specific_work(mode_task_set, interval_length):
    # The actual work done by MS tasks is bounded by their DBF
    return calculate_dbf_for_task_set(mode_task_set, interval_length)

def check_sm_mdo_validity(system):
    for mode_i in system.modes:
        max_di_k = 0
        for task_i_k in mode_i.ms_tasks:
            if task_i_k.D > max_di_k:
                max_di_k = task_i_k.D

        min_transition_deadline = float('inf')
        for mode_j in system.modes:
            if mode_i != mode_j:
                for task_j_r in mode_j.ms_tasks:
                    # Assuming transition deadline is stored per task, per source mode
                    transition_deadline = task_j_r.get_transition_deadline(from_mode=mode_i)
                    if transition_deadline < min_transition_deadline:
                        min_transition_deadline = transition_deadline

        if max_di_k > min_transition_deadline:
            return False # Validity condition violated
    return True # Validity condition met
